window.POETRY_REGISTER("v5-strict-13-13-0-b456af740576.js",{"poems":[[49184,2],[49185,2],[52291,2],[54214,2],[55398,2],[57946,2],[109550,7],[109553,7],[109554,7],[143405,7],[180264,7],[181214,7],[181249,7],[189192,7],[230810,7],[233356,7],[233439,7],[233442,7],[270369,7],[285959,7],[288143,7],[293623,7],[293913,7],[303613,7],[324758,7],[345994,9],[575423,8],[589734,8],[593805,8],[650074,5],[654999,5],[680563,5]],"pairs":[["故可以越圆清方浊兮不始不终","何止乎居九流五常兮理家理国",0],["胡为乎冒进贪名践危途与倾辙","胡为乎怙权恃宠顾华饰与雕簪",1],["日本嵯峨天皇当唐元和长庆间","则是中唐时此书已流传日本矣",2],["何不类附而别出于无名氏之下","岂编者未知义净三藏即义净欤",3],["疑贯休同清越句入诗以赠方干","或清越为贯休早年所用之法名",4],["盖其始赵志作第八首呈徐长史","应此徐长史即徐司马有酬诗至",5],["合仁义以为冠兮结忠信而为佩","集道德以为裳兮服文章而为带",6],["伟夫子之正谅兮适遭世以离尤","悼祖宗之累积兮大命颠而逢忧",7],["肇公孙之璇源兮玄鸟降而生商","并禹稷之圣贤兮实惟桓拨之王",8],["历妫姒之世数兮道日跻于武汤","始伐罪于仇饷兮人怨咨而徯来",8],["顾寛仁之宜民兮天俾式于九围","谅除残而代虐兮犹云德之有惭",8],["念社稷之颠倾兮七庙无所凭依","帝眷在于有周兮抱祭器而焉归",8],["呼造物以致问兮吾将考乎太初","彼天地其孰始兮日与月其代除",9],["四荒漫其何极兮人胡为而中居","火何为而南宅兮水孰使其在北",9],["世徒知其已然兮遂推类而立说","彼厥初其谁造兮孰布施而殊别",9],["十方大地是我一个身便能禁足","十方众生是我一个汉方解护生",10],["藏天下于天下兮一性自然平等","出世间于世间兮万像谁敢相谩",11],["六和合而无功兮脱略三千之界","万差别而有据兮齐承一点之恩",12],["不可以一朝风月昧却万古长空","不可以万古长空不明一朝风月",13],["完予独而息黥兮𪾢新功以自课","一息怳三秋兮胡为去我而他之",14],["匣以明月通天虹玉烛银之宝室","可以陆剸犀象水断潜伏之蛟虬",15],["㨫芳蘅与若英兮备杂菜之芬馨","将日昃之与期兮指潜波而为盟",16],["何蜂虫之阴戾琐微兮藏形于暗","骑蛇头而啜之兮堕厥颐而脱颔",17],["岂如吾乡华顶一峰八万四千丈","下蟠夭夭矫矫奇奇怪怪之苍松",18],["礧砢蹙缩轮囷拥肿可挫不可辱","坚刚正独盘薄偃蹇受命不受封",18],["无用之用不器之器振古成自晚","天台道人何苦汲汲图象寄涪翁",18],["月浸观音石兮恍有金身现普陀","风号玉女峰兮疑是湘江虞妃啼",19],["作诗勉同志兮欲倩仙掌摩丹崖","我醉挥椽笔兮大书特书而留题",19],["陶一气之奇佹兮奄宇宙之几何","握异采之陆离兮蹇儃佪而逶迤",20],["媲城东之作家兮付佛身于等幻","秉月上之迅机兮应日用而常亲",21],["如千手异执千目异顾元同一身","似万派争流百川竞注皆归一水",22],["惊起西川大蓬山上石女泪双垂","引得扶桑巨福山中木人空叹息",23],["君今策杖蜡屐走险一一当遍历","须令向禽宗炳之辈叹羡而莫及",24],["虽偈偈均约素兮能不汨乎物迁","岂好修以矫行兮余疑信之未分",25],["陆有重岩峻岭万仞镵天之剑阁","水有砅雷掣电悬流怒吼之江关",26],["羌世上之浮名兮曾不可以与谋","彼器溢而𫗧覆兮乐曾不免乎忧",27],["谋人国而不善兮宁颠蹶之愆尤","进阳阿之妙舞兮发南国之新讴",27],["无毁誉之拂膺兮无简书之侮予","胡为乎市之中兮冒埃壒之纷如",28],["有孝行的君王还载着个木父亲","满街上拖男领女去领钜桥的粟",29],["可恨那论成败的肉眼说现成话","胡褒贬那六出祁山的不晓六韬",29],["悲如渐离击筑燕人慷慨泣市上","惨如荆卿依柱秦帝辟易走宫中",30],["乍愿君如天上之月出海复东来","不愿君如东流之水到海不复回",31]]});
